INSERT INTO articles (id, title, body) VALUES
  (1, 'Understanding React Hooks', 'React hooks let you use state and other React features without writing a class. useEffect and useState are the two you will reach for first.'),
  (2, 'Advanced React Patterns', 'Custom hooks compose behaviour. This article covers hooks, context and render props in depth.'),
  (3, 'Node.js Streams in Practice', 'Backpressure, pipelines and transform streams for large file processing.'),
  (4, 'MySQL Index Internals', 'B+ tree pages, leftmost prefix rules and covering indexes explained with EXPLAIN output.'),
  (5, 'TypeScript Generics', 'Constraints, conditional types and inference in real codebases.');
